import{_ as r,C as t,o as i,c as s,E as a,a2 as l}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/authority-scope-20260910/02-concurrency-domain.figure.en.png",w=JSON.parse('{"title":"The Concurrency Limit Is One. Why Can Two Tasks Still Run?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Concurrency Limit Is One. Why Can Two Tasks Still Run?","date":"2026-09-10","published_date":"2026-09-10","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The Concurrency Limit Is One. Why Can Two Tasks Still Run?","summary":"A controlled AG2 experiment separates a repaired per-loop limit from the different contract of an Agent-wide resource cap.","cover":"/assets/authority-scope-20260910/02-concurrency-domain.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source seam experiments; not full-system validation","pageClass":"authority-scope-article"},"headers":[],"relativePath":"en/engineering/2026-09-10-concurrency-domain.md","filePath":"en/engineering/2026-09-10-concurrency-domain.md","lastUpdated":1789010602000}'),h={name:"en/engineering/2026-09-10-concurrency-domain.md"};function d(p,e,u,m,g,f){const o=t("ArticleCover"),n=t("ArticleTableScroll");return i(),s("div",null,[a(o,{image:"/assets/authority-scope-20260910/02-concurrency-domain.cover-v1.png",kicker:"Open-source Engineering · Experiments",title:"The Concurrency Limit Is One. Why Can Two Tasks Still Run?",summary:"A controlled AG2 experiment separates a repaired per-loop limit from the different contract of an Agent-wide resource cap.",version:"2026-09-10",languageHref:"/zh/engineering/2026-09-10-concurrency-domain",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-concurrency-limit-is-one-why-can-two-tasks-still-run" tabindex="-1">The Concurrency Limit Is One. Why Can Two Tasks Still Run? <a class="header-anchor" href="#the-concurrency-limit-is-one-why-can-two-tasks-still-run" aria-label="Permalink to &quot;The Concurrency Limit Is One. Why Can Two Tasks Still Run?&quot;">​</a></h1><p>An Agent is configured with <code>max_concurrency=1</code>. Two threads use it, and two subtasks run simultaneously. Has the configuration been violated?</p><p>If the limit belongs to the whole Agent, yes. If each event loop owns one slot, both tasks can run while respecting their respective limits.</p><p>That distinction matters when a limit protects an API account, a sandbox pool or a spending budget. Before evaluating whether a concurrency fix works, we need to identify the domain whose activity is being counted.</p><h2 id="reproducing-the-actual-defect" tabindex="-1">Reproducing the actual defect <a class="header-anchor" href="#reproducing-the-actual-defect" aria-label="Permalink to &quot;Reproducing the actual defect&quot;">​</a></h2><p>AG2 is an open-source framework for building and coordinating Agents. <a href="https://github.com/ag2ai/ag2/pull/3243" target="_blank" rel="noreferrer">PR #3243</a> changes the semaphore cache used when admitting subtasks. A semaphore supplies a limited number of slots: later coroutines wait when all slots are occupied, and a completed task releases its slot.</p><p>The earlier method stored one semaphore and its owning event loop on the Agent. When another loop arrived, it replaced the cached semaphore. Threads alternating between loops could keep replacing that reference while earlier tasks still occupied older semaphores.</p><p>We pinned the base and head source and executed the original <code>_spawn_subtask</code> method. The subtask body was a waiting counter, not a model call. Rather than relying on random scheduling, we arranged an explicit interleaving:</p><ol><li>A1 enters on loop A and holds a slot.</li><li>B1 enters on loop B in another real OS thread.</li><li>While both remain active, A requests A2.</li><li>We record local and aggregate peaks, then release the tasks.</li></ol><p>On the old method, A2 obtained a newly created slot. Loop A now had two active subtasks and the experiment had three overall. This violates even the narrower per-loop interpretation of a limit of one.</p><h2 id="which-peak-becomes-one-after-the-fix" tabindex="-1">Which peak becomes one after the fix? <a class="header-anchor" href="#which-peak-becomes-one-after-the-fix" aria-label="Permalink to &quot;Which peak becomes one after the fix?&quot;">​</a></h2><p>The proposed implementation keeps a semaphore for each running event loop and protects lookup and creation with a thread lock. B no longer replaces A&#39;s entry. Under the same interleaving, A2 waits for A1 to release its slot.</p><table tabindex="0"><thead><tr><th>Revision and execution shape</th><th style="text-align:right;">Loop A peak</th><th style="text-align:right;">Loop B peak</th><th style="text-align:right;">Aggregate peak</th></tr></thead><tbody><tr><td>Base, one loop</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>Base, two loops</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr><tr><td>Proposed head, one loop</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>Proposed head, two loops</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td></tr></tbody></table><p>We ran each configuration five times per round, across two rounds: forty controlled trials with identical outcomes and no exceptions. Recording both local and aggregate peaks makes the result precise. The proposed method repaired the per-loop limit; two loops still ran two subtasks in aggregate.</p><p><img src="'+c+'" alt="Local and aggregate peaks from the same controlled experiment"></p><p><em>Figure 1. These are in-flight synthetic waiting subtasks, not measurements of model requests, throughput or cost. Source: saved rounds 1 and 2 of our pinned-source experiments.</em></p><p>The upstream regression test explicitly targets the per-loop contract. An aggregate peak of two should therefore not be called a failed fix. It identifies a different guarantee that this patch does not provide.</p><h2 id="turn-the-number-into-an-acceptance-contract" tabindex="-1">Turn the number into an acceptance contract <a class="header-anchor" href="#turn-the-number-into-an-acceptance-contract" aria-label="Permalink to &quot;Turn the number into an acceptance contract&quot;">​</a></h2><p>A limit intended to protect a real resource needs at least four definitions.</p><p>The first is its <strong>scope</strong>: loop, Agent, process, host or tenant. The second is its <strong>admission authority</strong>: which object or service can issue slots, and whether all relevant executors share it. The third is its <strong>lifetime</strong>: what task completion, process exit, lease expiry or manual cleanup means for an occupied slot. The fourth is its <strong>uncertainty policy</strong>: losing sight of an old task does not establish that the resource it held is free.</p><p>A user may select one to prevent two expensive tasks from using the same account simultaneously. A correct semaphore in each loop could still fail to satisfy that product requirement. Conversely, a product deliberately promising one task per loop should not silently impose cross-domain serialization in the name of safety and remove intended parallelism.</p><p>The design starts with the contract, followed by the appropriate lock, shared counter or lease. A lock around creation protects that operation. It does not automatically turn separate counters into a shared resource budget.</p><h2 id="what-this-experiment-establishes" tabindex="-1">What this experiment establishes <a class="header-anchor" href="#what-this-experiment-establishes" aria-label="Permalink to &quot;What this experiment establishes&quot;">​</a></h2><p>We did not run a complete AG2 Agent, toolchain or model service, and did not test multiple processes, hosts or tenants. Initialization was a version-matched fixture; the admission method itself came from pinned upstream source. The PR remained open at the time of our inspection.</p><p>The useful acceptance question is therefore not only “did the peak exceed the cap?” It is also <strong>“within which domain did we count that peak?”</strong> Without that domain, the limit is difficult both to implement and to review fairly.</p><p><a href="/joinwell52/zh/engineering/2026-09-10-concurrency-domain">中文</a> · <a href="/joinwell52/en/research/evidence/2026-09-10-authority-scope">Methods, pinned revisions and raw results</a></p>',26))])}const b=r(h,[["render",d]]);export{w as __pageData,b as default};
